This is because:

1) The fsync task is holding an inode's delayed node mutex (for a
   directory) while calling __btrfs_update_delayed_inode() and that needs
   to do a search on the subvolume's btree (therefore read lock some
   extent buffers);

2) The lookup task, at btrfs_lookup(), triggered reclaim with the
   GFP_KERNEL allocation done by btrfs_init_file_extent_tree() while
   holding a read lock on a subvolume leaf;

3) The reclaim triggered kswapd which is doing inode eviction for the
   directory inode the fsync task is using as an argument to
   btrfs_commit_inode_delayed_inode() - but in that call chain we are
   trying to read lock the same leaf that the lookup task is holding
   while calling btrfs_init_file_extent_tree() and doing the GFP_KERNEL
   allocation.

Fix this by calling btrfs_init_file_extent_tree() after we don't need the
path anymore and release it in btrfs_read_locked_inode().

Reported-by: Thomas Hellström <thomas.hellstrom@linux.intel.com>
Link: https://lore.kernel.org/linux-btrfs/6e55113a22347c3925458a5d840a18401a38b276.camel@linux.intel.com/
Fixes: 8679d2687c35 ("btrfs: initialize inode::file_extent_tree after i_mode has been set")
Reviewed-by: Qu Wenruo <wqu@suse.com>
Signed-off-by: Filipe Manana <fdmanana@suse.com>
Reviewed-by: David Sterba <dsterba@suse.com>
Signed-off-by: David Sterba <dsterba@suse.com>

Here is the root cause:
The bug is a circular locking dependency caused by holding a read lock on a leaf (via a path) in the subvolume tree while performing a GFP_KERNEL memory allocation in btrfs_init_file_extent_tree(). This allocation can trigger reclaim, which may attempt to acquire the same lock (e.g., during writeback or other operations), leading to a deadlock condition detected by lockdep.

Here is the patch:
  */
 static int btrfs_read_locked_inode(struct btrfs_inode *inode, struct btrfs_path *path)
 {
 	struct btrfs_root *root = inode->root;
 	struct btrfs_fs_info *fs_info = root->fs_info;
 	struct extent_buffer *leaf;
 	struct btrfs_inode_item *inode_item;
 	struct inode *vfs_inode = &inode->vfs_inode;
 	struct btrfs_key location;
 	unsigned long ptr;
 	int maybe_acls;
 	u32 rdev;
 	int ret;
 	bool filled = false;
 	int first_xattr_slot;

 	ret = btrfs_fill_inode(inode, &rdev);
 	if (!ret)
 		filled = true;

 	ASSERT(path);

 	btrfs_get_inode_key(inode, &location);

 	ret = btrfs_lookup_inode(NULL, root, path, &location, 0);
 	if (ret) {
 		/*
 		 * ret > 0 can come from btrfs_search_slot called by
 		 * btrfs_lookup_inode(), this means the inode was not found.
 		 */
 		if (ret > 0)
 			ret = -ENOENT;
 		goto out;
 	}

 	leaf = path->nodes[0];

 	if (filled)
 		goto cache_index;

 	inode_item = btrfs_item_ptr(leaf, path->slots[0],
 				    struct btrfs_inode_item);
 	vfs_inode->i_mode = btrfs_inode_mode(leaf, inode_item);
 	set_nlink(vfs_inode, btrfs_inode_nlink(leaf, inode_item));
 	i_uid_write(vfs_inode, btrfs_inode_uid(leaf, inode_item));
 	i_gid_write(vfs_inode, btrfs_inode_gid(leaf, inode_item));
 	btrfs_i_size_write(inode, btrfs_inode_size(leaf, inode_item));

 	inode_set_atime(vfs_inode, btrfs_timespec_sec(leaf, &inode_item->atime),
 			btrfs_timespec_nsec(leaf, &inode_item->atime));

 	inode_set_mtime(vfs_inode, btrfs_timespec_sec(leaf, &inode_item->mtime),
 			btrfs_timespec_nsec(leaf, &inode_item->mtime));

 	inode_set_ctime(vfs_inode, btrfs_timespec_sec(leaf, &inode_item->ctime),
 			btrfs_timespec_nsec(leaf, &inode_item->ctime));

 	inode->i_otime_sec = btrfs_timespec_sec(leaf, &inode_item->otime);
 	inode->i_otime_nsec = btrfs_timespec_nsec(leaf, &inode_item->otime);

 	inode_set_bytes(vfs_inode, btrfs_inode_nbytes(leaf, inode_item));
 	inode->generation = btrfs_inode_generation(leaf, inode_item);
 	inode->last_trans = btrfs_inode_transid(leaf, inode_item);

 	inode_set_iversion_queried(vfs_inode, btrfs_inode_sequence(leaf, inode_item));
 	vfs_inode->i_generation = inode->generation;
 	vfs_inode->i_rdev = 0;
 	rdev = btrfs_inode_rdev(leaf, inode_item);

 	if (S_ISDIR(vfs_inode->i_mode))
 		inode->index_cnt = (u64)-1;

 	btrfs_inode_split_flags(btrfs_inode_flags(leaf, inode_item),
 				&inode->flags, &inode->ro_flags);
 	btrfs_update_inode_mapping_flags(inode);
 	btrfs_set_inode_mapping_order(inode);

 cache_index:
-	ret = btrfs_init_file_extent_tree(inode);
-	if (ret)
-		goto out;
-	btrfs_inode_set_file_extent_range(inode, 0,
-			round_up(i_size_read(vfs_inode), fs_info->sectorsize));
 	/*
 	 * If we were modified in the current generation and evicted from memory
 	 * and then re-read we need to do a full sync since we don't have any
 	 * idea about which extents were modified before we were evicted from
 	 * cache.
 	 *
 	 * This is required for both inode re-read from disk and delayed inode
 	 * in the delayed_nodes xarray.
 	 */
 	if (inode->last_trans == btrfs_get_fs_generation(fs_info))
 		set_bit(BTRFS_INODE_NEEDS_FULL_SYNC, &inode->runtime_flags);

 	/*
 	 * We don't persist the id of the transaction where an unlink operation
 	 * against the inode was last made. So here we assume the inode might
 	 * have been evicted, and therefore the exact value of last_unlink_trans
 	 * lost, and set it to last_trans to avoid metadata inconsistencies
 	 * between the inode and its parent if the inode is fsync'ed and the log
 	 * replayed. For example, in the scenario:
 	 *
 	 * touch mydir/foo
 	 * ln mydir/foo mydir/bar
 	 * sync
 	 * unlink mydir/bar
 	 * echo 2 > /proc/sys/vm/drop_caches   # evicts inode
 	 * xfs_io -c fsync mydir/foo
 	 * <power failure>
 	 * mount fs, triggers fsync log replay
 	 *
 	 * We must make sure that when we fsync our inode foo we also log its
 	 * parent inode, otherwise after log replay the parent still has the
 	 * dentry with the "bar" name but our inode foo has a link count of 1
 	 * and doesn't have an inode ref with the name "bar" anymore.
 	 *
 	 * Setting last_unlink_trans to last_trans is a pessimistic approach,
 	 * but it guarantees correctness at the expense of occasional full
 	 * transaction commits on fsync if our inode is a directory, or if our
 	 * inode is not a directory, logging its parent unnecessarily.
 	 */
 	inode->last_unlink_trans = inode->last_trans;

 	/*
 	 * Same logic as for last_unlink_trans. We don't persist the generation
 	 * of the last transaction where this inode was used for a reflink
 	 * operation, so after eviction and reloading the inode we must be
 	 * pessimistic and assume the last transaction that modified the inode.
 	 */
 	inode->last_reflink_trans = inode->last_trans;

 	path->slots[0]++;
 	if (vfs_inode->i_nlink != 1 ||
 	    path->slots[0] >= btrfs_header_nritems(leaf))
 		goto cache_acl;

 	btrfs_item_key_to_cpu(leaf, &location, path->slots[0]);
 	if (location.objectid != btrfs_ino(inode))
 		goto cache_acl;

 	ptr = btrfs_item_ptr_offset(leaf, path->slots[0]);
 	if (location.type == BTRFS_INODE_REF_KEY) {
 		struct btrfs_inode_ref *ref;

 		ref = (struct btrfs_inode_ref *)ptr;
 		inode->dir_index = btrfs_inode_ref_index(leaf, ref);
 	} else if (location.type == BTRFS_INODE_EXTREF_KEY) {
 		struct btrfs_inode_extref *extref;

 		extref = (struct btrfs_inode_extref *)ptr;
 		inode->dir_index = btrfs_inode_extref_index(leaf, extref);
 	}
 cache_acl:
 	/*
 	 * try to precache a NULL acl entry for files that don't have
 	 * any xattrs or acls
 	 */
 	maybe_acls = acls_after_inode_item(leaf, path->slots[0],
 					   btrfs_ino(inode), &first_xattr_slot);
 	if (first_xattr_slot != -1) {
 		path->slots[0] = first_xattr_slot;
 		ret = btrfs_load_inode_props(inode, path);
 		if (ret)
 			btrfs_err(fs_info,
 				  "error loading props for ino %llu (root %llu): %d",
 				  btrfs_ino(inode), btrfs_root_id(root), ret);
 	}

+	/*
+	 * We don't need the path anymore, so release it to avoid holding a read
+	 * lock on a leaf while calling btrfs_init_file_extent_tree(), which can
+	 * allocate memory that triggers reclaim (GFP_KERNEL) and cause a locking
+	 * dependency.
+	 */
+	btrfs_release_path(path);
+
+	ret = btrfs_init_file_extent_tree(inode);
+	if (ret)
+		goto out;
+	btrfs_inode_set_file_extent_range(inode, 0,
+			  round_up(i_size_read(vfs_inode), fs_info->sectorsize));
+
 	if (!maybe_acls)
 		cache_no_acl(vfs_inode);

 	switch (vfs_inode->i_mode & S_IFMT) {
 	case S_IFREG:
 		vfs_inode->i_mapping->a_ops = &btrfs_aops;
 		vfs_inode->i_fop = &btrfs_file_operations;
 		vfs_inode->i_op = &btrfs_file_inode_operations;
 		break;
 	case S_IFDIR:
 		vfs_inode->i_fop = &btrfs_dir_file_operations;
 		vfs_inode->i_op = &btrfs_dir_inode_operations;
 		break;
 	case S_IFLNK:
 		vfs_inode->i_op = &btrfs_symlink_inode_operations;
 		inode_nohighmem(vfs_inode);
 		vfs_inode->i_mapping->a_ops = &btrfs_aops;
 		break;
 	default:
 		vfs_inode->i_op = &btrfs_special_inode_operations;
 		init_special_inode(vfs_inode, vfs_inode->i_mode, rdev);
 		break;
 	}

 	btrfs_sync_inode_flags_to_i_flags(inode);

 	ret = btrfs_add_inode_to_root(inode, true);
 	if (ret)
 		goto out;

 	return 0;
 out:
 	iget_failed(vfs_inode);
 	return ret;
 }



